import React from 'react';
import { useApp } from '../context/AppContext';

const detectionColors = {
  Normal: '#22c55e', Phone: '#60a5fa', Medical_Mask: '#34d399',
  Fire: '#ef4444', Smoke: '#94a3b8', Gun: '#f87171',
  Knife: '#facc15', Falling: '#a78bfa', Violence: '#a855f7', Theft_Mask: '#fbbf24'
};

const threatBorder = {
  Fire: '#7f1d1d', Violence: '#7f1d3f', Gun: '#7f1d1d',
  Knife: '#7f6d00', Smoke: '#2d2d2d'
};

function LiveDot() {
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 9, color: '#22c55e' }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#22c55e', display: 'inline-block', animation: 'livePulse 1.5s infinite' }} />
      Live
      <style>{`@keyframes livePulse{0%,100%{opacity:1}50%{opacity:.3}}`}</style>
    </span>
  );
}

function OfflineDot() {
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 9, color: '#64748b' }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#64748b', display: 'inline-block' }} />
      Offline
    </span>
  );
}

export default function CameraGrid() {
  const { cameras } = useApp();

  const onlineCams  = cameras.filter(c => c.status === 'online');
  const totalSlots  = 6;
  const emptySlots  = totalSlots - cameras.length;

  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
        <span style={{ color: '#3b82f6', fontSize: 14 }}>📷</span>
        <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>
          Live Cameras
        </span>
        <span style={{ fontSize: 10, color: '#64748b', marginLeft: 4 }}>
          ({onlineCams.length} online)
        </span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 8 }}>
        {cameras.map(cam => {
          const isOnline   = cam.status === 'online';
          const lastClass  = cam.last_class  || 'Normal';
          const lastConf   = cam.last_conf   || 0.92;
          const detColor   = detectionColors[lastClass] || '#22c55e';
          const borderCol  = isOnline ? (threatBorder[lastClass] || '#1e2d47') : '#1e2d47';

          return (
            <div key={cam.id} style={{
              background: '#151d2e',
              border: `1px solid ${borderCol}`,
              borderRadius: 8, overflow: 'hidden',
              opacity: isOnline ? 1 : 0.6
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '5px 8px', background: '#1a2340' }}>
                <span style={{ fontSize: 10, fontWeight: 600, color: '#e2e8f0' }}>{cam.name}</span>
                {isOnline ? <LiveDot /> : <OfflineDot />}
              </div>

              <div style={{ height: 110, background: '#080f1a', position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {isOnline ? (
                  <>
                    <span style={{ fontSize: 11, color: '#1e3a5f' }}>[ Live Feed ]</span>
                    <div style={{
                      position: 'absolute', top: '20%', left: '15%',
                      border: `2px solid ${detColor}`, borderRadius: 4,
                      padding: '2px 6px', fontSize: 9, fontWeight: 700,
                      color: detColor, background: `${detColor}22`
                    }}>
                      {lastClass} {lastConf}
                    </div>
                  </>
                ) : (
                  <span style={{ fontSize: 11, color: '#64748b' }}>[ Offline ]</span>
                )}
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '4px 8px', background: '#1a2340' }}>
                {['📷', '⛶', '⋯'].map((ic, i) => (
                  <span key={i} style={{ fontSize: 12, color: '#64748b', cursor: 'pointer' }}>{ic}</span>
                ))}
                <div style={{ display: 'flex', gap: 1, alignItems: 'flex-end' }}>
                  {[4, 6, 8, 10].map((h, i) => (
                    <span key={i} style={{ width: 2, height: h, background: isOnline ? '#22c55e' : '#253550', borderRadius: 1, display: 'block' }} />
                  ))}
                </div>
              </div>
            </div>
          );
        })}

        {Array.from({ length: Math.max(0, emptySlots) }).map((_, i) => (
          <div
            key={`empty-${i}`}
            style={{
              background: '#151d2e', border: '1px dashed #253550',
              borderRadius: 8, height: 148,
              display: 'flex', flexDirection: 'column',
              alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer', color: '#64748b', gap: 5, transition: 'all .2s'
            }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = '#3b82f6'; e.currentTarget.style.color = '#3b82f6'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = '#253550'; e.currentTarget.style.color = '#64748b'; }}
          >
            <span style={{ fontSize: 26 }}>+</span>
            <span style={{ fontSize: 11, fontWeight: 600 }}>Add Camera</span>
            <span style={{ fontSize: 9 }}>Click to add new camera</span>
          </div>
        ))}
      </div>
    </div>
  );
}
